कर्म bubble_sort(arr) {
    n = arr.लंबाई()
    के_लिए i में range(n) {
        के_लिए j में range(0, n-i-1) {
            यदि arr[j] > arr[j+1] {
                arr[j], arr[j+1] = arr[j+1], arr[j]
            }
        }
    }
    लौटाओ arr
}

कर्म quick_sort(arr) {
    यदि arr.लंबाई() <= 1 {
        लौटाओ arr
    }
    pivot = arr[arr.लंबाई() // 2]
    left = [x के_लिए x में arr यदि x < pivot]
    middle = [x के_लिए x में arr यदि x == pivot]
    right = [x के_लिए x में arr यदि x > pivot]
    लौटाओ quick_sort(left) + middle + quick_sort(right)
}

कर्म merge_sort(arr) {
    यदि arr.लंबाई() <= 1 {
        लौटाओ arr
    }
    mid = arr.लंबाई() // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])
    लौटाओ merge(left, right)
}
कर्म merge(left, right) {
    result = []
    i = 0, j = 0
    जबतक i < left.लंबाई() और j < right.लंबाई() {
        यदि left[i] <= right[j] {
            result.जोडें(left[i])
            i += 1
        } और {
            result.जोडें(right[j])
            j += 1
        }
    }
    result.जोडें(left[i:])
    result.जोडें(right[j:])
    लौटाओ result
}

कर्म binary_search(arr, target) {
    low = 0
    high = arr.लंबाई() - 1
    जबतक low <= high {
        mid = (low + high) // 2
        यदि arr[mid] == target {
            लौटाओ mid
        } अन्य यदि arr[mid] < target {
            low = mid + 1
        } अन्य {
            high = mid - 1
        }
    }
    लौटाओ -1
}

कर्म linear_search(arr, target) {
    के_लिए i में range(arr.लंबाई()) {
        यदि arr[i] == target {
            लौटाओ i
        }
    }
    लौटाओ -1
}

कर्म bfs(graph, start) {
    visited = सेट()
    queue = [start]
    visited.जोडें(start)
    result = []
    जबतक queue.लंबाई() > 0 {
        node = queue.पहला()
        queue.हटाएं(0)
        result.जोडें(node)
        के_लिए neighbor में graph[node] {
            यदि neighbor not in visited {
                visited.जोडें(neighbor)
                queue.जोडें(neighbor)
            }
        }
    }
    लौटाओ result
}

कर्म dfs(graph, start, visited=None) {
    यदि visited == None {
        visited = सेट()
    }
    visited.जोडें(start)
    result = [start]
    के_लिए neighbor में graph[start] {
        यदि neighbor not in visited {
            result.विस्तार(dfs(graph, neighbor, visited))
        }
    }
    लौटाओ result
}

कर्म dijkstra(graph, start) {
    distances = {node: अनंत के_लिए node में graph.nodes}
    distances[start] = 0
    visited = सेट()
    जबतक visited.लंबाई() < graph.nodes.लंबाई() {
        # Find unvisited node with minimum distance
        min_node = None
        के_लिए node में graph.nodes {
            यदि node not in visited और (min_node == None या distances[node] < distances[min_node]) {
                min_node = node
            }
        }
        यदि min_node == None {
            तोडें
        }
        visited.जोडें(min_node)
        के_लिए neighbor, weight में graph[min_node] {
            new_dist = distances[min_node] + weight
            यदि new_dist < distances[neighbor] {
                distances[neighbor] = new_dist
            }
        }
    }
    लौटाओ distances
}

श्रेणी HashTable {
    परिवर्तनी buckets = []
    कर्म __init__(capacity=16) {
        buckets = [{} के_लिए _ में range(capacity)]
    }
    कर्म _hash(key) {
        लौटाओ hash(key) % buckets.लंबाई()
    }
    कर्म put(key, value) {
        idx = _hash(key)
        buckets[idx][key] = value
    }
    कर्म get(key) {
        idx = _hash(key)
        लौटाओ buckets[idx].get(key)
    }
    कर्म delete(key) {
        idx = _hash(key)
        यदि key in buckets[idx] {
            हटाएं buckets[idx][key]
        }
    }
}

कर्म fibonacci(n, memo={}) {
    यदि n in memo {
        लौटाओ memo[n]
    }
    यदि n <= 1 {
        लौटाओ n
    }
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    लौटाओ memo[n]
}
